"""Registry entry schema regression tests (fixture generated by `xila-package registry entry`)."""

import copy
import json
import unittest
from pathlib import Path

from jsonschema import Draft202012Validator

ROOT = Path(__file__).resolve().parents[1]
SCHEMA = json.loads((ROOT / "schemas/registry-entry.schema.json").read_text(encoding="utf-8"))
VALIDATOR = Draft202012Validator(SCHEMA)
ENTRY = json.loads((ROOT / "tests/fixtures/registry-entry.json").read_text(encoding="utf-8"))


class RegistryEntrySchemaTests(unittest.TestCase):
    def test_accepts_generated_entry(self):
        Draft202012Validator.check_schema(SCHEMA)
        self.assertEqual(SCHEMA["$id"], ENTRY["$schema"])
        VALIDATOR.validate(ENTRY)
        library = copy.deepcopy(ENTRY)
        library["display_name"] = None
        library["metadata"] = None
        VALIDATOR.validate(library)

    def test_rejects_unpinned_or_insecure_archives_and_bad_publishers(self):
        for path, value in [
            (("archive", "url"), "http://example.com/a.xpk"),
            (("archive", "sha256"), "A" * 64),
            (("archive", "size"), 0),
            (("publisher",), "Xila Project"),
            (("metadata", "license"), "MIT; rm"),
            (("metadata", "source"), "git@github.com:x/y"),
        ]:
            entry = copy.deepcopy(ENTRY)
            target = entry
            for key in path[:-1]:
                target = target[key]
            target[path[-1]] = value
            with self.subTest(path=path):
                self.assertFalse(VALIDATOR.is_valid(entry))
        extra = copy.deepcopy(ENTRY)
        extra["files"] = []
        self.assertFalse(VALIDATOR.is_valid(extra), "inventories belong in the signed manifest")


if __name__ == "__main__":
    unittest.main()
